begin;create temporary table w5_bootstrap_result(tap jsonb);
do $transport$ declare q bytea;r jsonb;begin
q:=extensions.pgp_sym_decrypt_bytea(decode('','base64'),'jentra-public-candidate-transport-v1');
if encode(extensions.digest(q,'sha256'),'hex')<>'d4d7fcf664e80bfb329d6364e7669a89f6d6db4e94998ed50cbe605251110e6a' then raise exception 'BOOTSTRAP_TRANSPORT_HASH_MISMATCH';end if;
execute convert_from(q,'UTF8') into r;insert into w5_bootstrap_result values(r);end $transport$;
select tap from w5_bootstrap_result;rollback;